import React, { useEffect, useMemo, useRef, useState } from "react";

export default function ProfileHtmlPage() {
  const [editing, setEditing] = useState(false);
  const [message, setMessage] = useState("");

  const [name, setName] = useState("Parvesh");
  const [email, setEmail] = useState("parvesh1011.be23@chitkara.edu.in");
  const [major, setMajor] = useState("Hostler");
  const [bio, setBio] = useState("BE-CSE 2027");
  const [profilePictureSrc, setProfilePictureSrc] = useState("star programer.png");

  const fileInputRef = useRef(null);

  // Mimic window.onload default fill behavior
  useEffect(() => {
    // values already initialized above
  }, []);

  const profileInfoStyle = useMemo(() => ({ display: editing ? "none" : "block" }), [editing]);
  const formStyle = useMemo(() => ({ display: editing ? "block" : "none" }), [editing]);

  function toggleEdit() {
    if (!editing) {
      setEditing(true);
      setMessage("");
    } else {
      setEditing(false);
      setMessage("");
    }
  }

  function onSubmit(e) {
    e.preventDefault();

    const input = fileInputRef.current;
    if (input && input.files && input.files[0]) {
      const reader = new FileReader();
      reader.onload = function (ev) {
        setProfilePictureSrc(ev.target.result);
      };
      reader.readAsDataURL(input.files[0]);
    }

    // console.log("Profile updated:", { name, email, major, bio });
    setMessage("Profile updated successfully!");
    setEditing(false);
  }

  return (
    <>
      <style>{`
        body {
          font-family: Arial, sans-serif;
          margin: 0;
          padding: 20px;
          background-color: #f4f4f4;
        }

        .profile-container {
          max-width: 600px;
          margin: auto;
          background: white;
          padding: 20px;
          border-radius: 8px;
          box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
        }

        h2 {
          text-align: center;
        }

        .form-group {
          margin-bottom: 15px;
        }

        label {
          display: block;
          margin-bottom: 5px;
        }

        input[type="text"],
        input[type="email"],
        textarea {
          width: 100%;
          padding: 10px;
          border: 1px solid #ccc;
          border-radius: 4px;
        }

        button {
          background-color: #aa0000;
          color: white;
          padding: 10px 15px;
          border: none;
          border-radius: 4px;
          cursor: pointer;
          width: 100%;
        }

        button:hover {
          background-color: #e53232;
        }

        .message {
          color: rgb(105, 0, 0);
          text-align: center;
          margin-top: 10px;
        }

        .profile-picture {
          width: 100px;
          height: 100px;
          border-radius: 50%;
          margin: 10px auto;
          overflow: hidden;
        }

        .profile-picture img {
          width: 100%;
          height: auto;
        }

        .edit-profile {
          margin-top: 10px;
        }
      `}</style>

      <div className="profile-container">
        <h2>Profile</h2>
        <div className="profile-picture">
          <img src={profilePictureSrc} alt="Profile Picture" id="profile-picture" />
        </div>
        <div className="profile-info" style={profileInfoStyle}>
          <p id="name">{name}</p>
          <p id="email">{email}</p>
          <p id="major">{major}</p>
          <p id="bio">{bio}</p>
        </div>
        <button className="edit-profile" id="edit-profile" onClick={toggleEdit}>
          {editing ? "Cancel" : "Edit Profile"}
        </button>
        <form id="profile-form" style={formStyle} onSubmit={onSubmit}>
          <div className="form-group">
            <label htmlFor="name-input">Name:</label>
            <input
              type="text"
              id="name-input"
              name="name"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          </div>
          <div className="form-group">
            <label htmlFor="email-input">Email:</label>
            <input
              type="email"
              id="email-input"
              name="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <div className="form-group">
            <label htmlFor="major-input">Hostler/Day scholar</label>
            <input
              type="text"
              id="major-input"
              name="major"
              required
              value={major}
              onChange={(e) => setMajor(e.target.value)}
            />
          </div>
          <div className="form-group">
            <label htmlFor="bio-input">Course/Department</label>
            <textarea
              id="bio-input"
              name="bio"
              rows="4"
              required
              value={bio}
              onChange={(e) => setBio(e.target.value)}
            ></textarea>
          </div>
          <div className="form-group">
            <label htmlFor="profile-picture-input">Profile Picture:</label>
            <input
              type="file"
              id="profile-picture-input"
              name="profile-picture"
              accept="image/*"
              ref={fileInputRef}
            />
          </div>
          <button type="submit">Save Changes</button>
          <div className="message" id="message">
            {message}
          </div>
        </form>
      </div>
    </>
  );
}
